using AssetForge.Core.Models;using AssetForge.Infrastructure.Data;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;namespace AssetForge.Web.Pages;public class PeopleModel(AssetForgeDbContext db):PageModel{public List<Person> People{get;set;}=[];public SelectList Departments{get;set;}=null!;[BindProperty]public Person Input{get;set;}=new();public async Task OnGetAsync(){People=await db.People.Include(x=>x.Department).OrderBy(x=>x.FullName).ToListAsync();Departments=new(await db.Departments.OrderBy(x=>x.Name).ToListAsync(),"Id","Name");}public async Task<IActionResult> OnPostAsync(){if(string.IsNullOrWhiteSpace(Input.FullName))return RedirectToPage();db.People.Add(Input);await db.SaveChangesAsync();return RedirectToPage();}}
